// Generated by hand from docs/API.md. Do not edit here; change docs/API.md and re-run api-designer.

// ---- Endpoint paths (relative to the API base URL, e.g. http://localhost:8000) ----
export const API_PATHS = {
  health: "/api/v1/health",
  roast: "/api/v1/roast",
} as const;

// ---- Limits (must match docs/API.md and apps/api/app/schemas.py) ----
export const ROAST_CODE_MAX_CHARS = 20000;
export const ROAST_FILE_NAME_MAX_CHARS = 255;
export const ASCII_ART_MAX_LINES = 20;
export const ASCII_ART_MAX_WIDTH = 60;
/** Client-side abort budget for POST /api/v1/roast; on expiry use the bank. */
export const ROAST_TIMEOUT_MS = 7000;

// ---- Error envelope (identical to app.main.error_body) ----
export interface ErrorDetail {
  code: ErrorCode | (string & {});
  message: string;
}

export interface ErrorEnvelope {
  error: ErrorDetail;
}

export type ErrorCode =
  | "ai_unavailable"
  | "ai_error"
  | "ai_timeout"
  | "validation_error"
  | "bad_request"
  | "not_found"
  | "internal_error";

// ---- Shared enums ----
/** "neutral" is never sent to the backend. */
export type RoastEmotion = "sad" | "happy" | "super-happy";
export type LineEmotion = "sad" | "happy";
export type AvatarId = "labubu" | "calhacks-bear" | "rubber-duck";
export type RoastMode = "profane" | "clean";

// ---- Health ----
export interface HealthResponse {
  status: "ok";
  supabase_configured: boolean;
  /** Retained for compatibility; always false. */
  anthropic_configured: boolean;
  /** True when the Ollama warm-up succeeded. Absent means unknown. */
  ai_configured?: boolean;
}

// ---- Roast ----
export interface RoastRequest {
  /** At most 20000 characters. */
  code: string;
  file_name?: string | null;
  emotion: RoastEmotion;
  avatar: AvatarId;
  mode: RoastMode;
}

export interface RoastLine {
  /** Comment-ready: no leading "# ", no newlines. */
  text: string;
  /** 1-based line number in the submitted code, or null. */
  line: number | null;
}

export interface RoastLinesResponse {
  kind: "lines";
  emotion: LineEmotion;
  avatar: AvatarId;
  mode: RoastMode;
  /** 2 to 4 items. */
  lines: RoastLine[];
}

export interface RoastReplacementResponse {
  kind: "replacement";
  emotion: "super-happy";
  avatar: AvatarId;
  mode: RoastMode;
  /** 2 to 3 comment-ready lines. */
  mock_lines: string[];
  /** 1 to 20 comment-ready lines, each at most 60 characters. */
  art_lines: string[];
}

export type RoastResponse = RoastLinesResponse | RoastReplacementResponse;
